package com.smartspend;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import jakarta.servlet.http.HttpServletResponse;import java.io.*;import java.math.*;import java.time.*;import java.util.*;import com.lowagie.text.Document;import com.lowagie.text.FontFactory;import com.lowagie.text.Paragraph;import com.lowagie.text.pdf.PdfWriter;
class ResourceNotFoundException extends RuntimeException{ResourceNotFoundException(String m){super(m);}} class ConflictException extends RuntimeException{ConflictException(String m){super(m);}} class BadRequestException extends RuntimeException{BadRequestException(String m){super(m);}} class UnauthorizedException extends RuntimeException{UnauthorizedException(String m){super(m);}}
@RestControllerAdvice class Errors{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<?> nf(ResourceNotFoundException e){return b(404,"Not Found",e.getMessage());}@ExceptionHandler(ConflictException.class)ResponseEntity<?> cf(ConflictException e){return b(409,"Conflict",e.getMessage());}@ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class)ResponseEntity<?> va(Exception e){return b(400,"Bad Request","Validation failed");}@ExceptionHandler(BadRequestException.class)ResponseEntity<?> ba(BadRequestException e){return b(400,"Bad Request",e.getMessage());}@ExceptionHandler(UnauthorizedException.class)ResponseEntity<?> ua(UnauthorizedException e){return b(401,"Unauthorized",e.getMessage());}@ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class)ResponseEntity<?> integrity(Exception e){return b(409,"Conflict","Category cannot be deleted because it is currently in use.");}@ExceptionHandler(Exception.class)ResponseEntity<?> ex(Exception e){return b(500,"Internal Server Error","Unexpected server error");}ResponseEntity<?> b(int s,String e,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s,"error",e,"message",m));}}
@RestController @RequestMapping("/api/dashboard") class DashboardController extends Base{final ExpenseRepo es;final IncomeRepo is;final UserRepo us;DashboardController(ExpenseRepo e,IncomeRepo i,UserRepo u){es=e;is=i;us=u;}@GetMapping Map<String,Object> dash(Authentication a){User u=me(a,us);var ae=es.findByUserIdOrderByDateDesc(u.id);var ai=is.findByUserIdOrderByDateDesc(u.id);BigDecimal inc=ai.stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add),exp=ae.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);LocalDate now=LocalDate.now(),start=now.withDayOfMonth(1),prev=start.minusMonths(1);LocalDate prevEnd=prev.plusDays(Math.min(now.getDayOfMonth()-1,prev.lengthOfMonth()-1));BigDecimal cm=es.findByUserIdAndDateBetween(u.id,start,now).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add),pm=es.findByUserIdAndDateBetween(u.id,prev,prevEnd).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,BigDecimal> cats=new LinkedHashMap<>();ae.forEach(e->cats.merge(e.category.name,e.amount,BigDecimal::add));BigDecimal bal=inc.subtract(exp);Map<String,Object> result=new LinkedHashMap<>();result.put("totalIncome",inc);result.put("totalExpense",exp);result.put("balance",bal);result.put("savings",bal);result.put("savingsPercentage",inc.signum()==0?0:bal.multiply(BigDecimal.valueOf(100)).divide(inc,2,RoundingMode.HALF_UP));result.put("currentMonthExpense",cm);result.put("currentMonthIncome",is.findByUserIdAndDateBetween(u.id,start,now).stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));result.put("previousMonthExpense",pm);result.put("spendingIncreased",cm.compareTo(pm)>0);result.put("categorySummary",cats);result.put("recentTransactions",ae.stream().limit(5).map(e->Map.of("description",e.description,"amount",e.amount,"date",e.date)).toList());return result;}}
@RestController @RequestMapping("/api/insights") class InsightController extends Base{final ExpenseRepo es;final BudgetRepo bs;final UserRepo us;final IncomeRepo incomes;final NotificationService notifications;InsightController(ExpenseRepo e,BudgetRepo b,UserRepo u,IncomeRepo i,NotificationService n){es=e;bs=b;us=u;incomes=i;notifications=n;}@GetMapping List<Map<String,String>> all(Authentication a){User u=me(a,us);LocalDate now=LocalDate.now(),monthStart=now.withDayOfMonth(1),previousStart=monthStart.minusMonths(1);var ex=es.findByUserIdAndDateBetween(u.id,monthStart,now);BigDecimal total=ex.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);List<Map<String,String>> out=new ArrayList<>();Map<String,BigDecimal> cats=new HashMap<>();ex.forEach(e->cats.merge(e.category.name,e.amount,BigDecimal::add));cats.forEach((n,v)->{if(FinancialRules.highCategorySpending(v,total))out.add(Map.of("type","CATEGORY","title","High category spending","message","High spending detected in "+n+".","severity","WARNING"));});LocalDate previousEnd=previousStart.plusDays(Math.min(now.getDayOfMonth()-1,previousStart.lengthOfMonth()-1));BigDecimal current=total,previous=es.findByUserIdAndDateBetween(u.id,previousStart,previousEnd).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);if(FinancialRules.spendingIncreased(current,previous)){out.add(Map.of("type","SPENDING_INCREASE","title","Spending increased","message","Spending increased compared with previous month.","severity","WARNING"));notifications.notify(u,"SPENDING_INCREASE","Spending increased compared with previous month.");}bs.findByUserId(u.id).forEach(b->{var from=LocalDate.of(b.year,b.month,1);var used=es.findByUserIdAndDateBetween(u.id,from,from.plusMonths(1).minusDays(1)).stream().filter(e->b.category==null||e.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);String status=FinancialRules.budgetStatus(used,b.amount);if("EXCEEDED".equals(status))out.add(Map.of("type","BUDGET","title","Budget exceeded","message","Your budget has been exceeded.","severity","DANGER"));else if("WARNING".equals(status))out.add(Map.of("type","BUDGET","title","Budget warning","message","You are approaching your budget limit.","severity","WARNING"));});BigDecimal income=incomes.findByUserIdAndDateBetween(u.id,monthStart,now).stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal savingsPct=FinancialRules.savingsPercentage(income,total);if(FinancialRules.lowSavings(income,total)){out.add(Map.of("type","SAVINGS","title","Low savings","message","Consider reducing non-essential expenses.","severity","INFO"));notifications.notify(u,"LOW_SAVINGS","Consider reducing non-essential expenses.");}return out;}}
@RestController @RequestMapping("/api/notifications") class NotificationController extends Base{final NotificationRepo ns;final UserRepo us;NotificationController(NotificationRepo n,UserRepo u){ns=n;us=u;}@GetMapping List<Map<String,Object>> all(Authentication a){return ns.findByUserIdOrderByCreatedAtDesc(me(a,us).id).stream().map(n->Map.<String,Object>of("id",n.id,"message",n.message,"type",n.type,"read",n.readFlag,"createdAt",n.createdAt)).toList();}@PutMapping("/read-all") ResponseEntity<?> readAll(Authentication a){var list=ns.findByUserIdOrderByCreatedAtDesc(me(a,us).id);list.forEach(n->n.readFlag=true);ns.saveAll(list);return ResponseEntity.noContent().build();}@PutMapping("/{id}/read") ResponseEntity<?> read(@PathVariable Long id,Authentication a){var n=ns.findByIdAndUserId(id,me(a,us).id).orElseThrow(()->new ResourceNotFoundException("Notification not found"));n.readFlag=true;ns.save(n);return ResponseEntity.noContent().build();}}
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") class AdminController{
 final UserRepo users; final CategoryRepo cats; final AuditRepo logs; final AuditService audit; final ExpenseRepo expenses; final IncomeRepo incomes; final BudgetRepo budgets;
 AdminController(UserRepo u,CategoryRepo c,AuditRepo l,AuditService a,ExpenseRepo e,IncomeRepo i,BudgetRepo b){users=u;cats=c;logs=l;audit=a;expenses=e;incomes=i;budgets=b;}
 @GetMapping("/users") List<Map<String,Object>> users(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"active",u.active,"createdAt",u.createdAt)).toList();}
 @PutMapping("/users/{id}/active") Map<String,Object> active(@PathVariable Long id,@RequestParam boolean value,Authentication auth){var target=users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));target.active=value;users.save(target);audit.record(users.findByEmail(auth.getName()).orElseThrow(()->new ResourceNotFoundException("Admin not found")),"USER_STATUS","Changed active status for "+target.email+" to "+value);return Map.of("id",target.id,"active",target.active);}
 @GetMapping("/stats") Map<String,Object> stats(){return Map.of("users",users.count(),"activeUsers",users.countByActive(true),"inactiveUsers",users.countByActive(false),"admins",users.countByRole(Role.ADMIN),"categories",cats.count());}
 @GetMapping("/audit-logs") List<Map<String,Object>> audit(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return logs.findPageByOrderByTimestampDesc(org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.min(200,Math.max(1,size)))).getContent().stream().map(x->Map.<String,Object>of("id",x.id,"action",x.action,"description",x.description,"timestamp",x.timestamp,"user",x.user==null?"system":x.user.email)).toList();}
 @GetMapping("/users/{id}/dashboard") Map<String,Object> userDashboard(@PathVariable Long id){
  User u=users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));
  var allExpenses=expenses.findByUserIdOrderByDateDesc(u.id); var allIncome=incomes.findByUserIdOrderByDateDesc(u.id);
  BigDecimal totalIncome=allIncome.stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);
  BigDecimal totalExpense=allExpenses.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);
  BigDecimal balance=totalIncome.subtract(totalExpense);
  LocalDate now=LocalDate.now(),start=now.withDayOfMonth(1),previousStart=start.minusMonths(1);
  LocalDate previousEnd=previousStart.plusDays(Math.min(now.getDayOfMonth()-1,previousStart.lengthOfMonth()-1));
  BigDecimal currentExpense=expenses.findByUserIdAndDateBetween(u.id,start,now).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);
  BigDecimal currentIncome=incomes.findByUserIdAndDateBetween(u.id,start,now).stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);
  BigDecimal previousExpense=expenses.findByUserIdAndDateBetween(u.id,previousStart,previousEnd).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);
  Map<String,BigDecimal> categories=new LinkedHashMap<>(); allExpenses.forEach(e->categories.merge(e.category.name,e.amount,BigDecimal::add));
  List<Map<String,Object>> budgetRows=new ArrayList<>(); budgets.findByUserId(u.id).stream().sorted(Comparator.comparingInt((Budget b)->b.year).reversed().thenComparingInt(b->b.month).reversed()).forEach(b->{var from=LocalDate.of(b.year,b.month,1);var to=from.plusMonths(1).minusDays(1);var used=expenses.findByUserIdAndDateBetween(u.id,from,to).stream().filter(e->b.category==null||e.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);double pct=b.amount.signum()==0?0:used.multiply(BigDecimal.valueOf(100)).divide(b.amount,2,RoundingMode.HALF_UP).doubleValue();budgetRows.add(Map.of("id",b.id,"amount",b.amount,"month",b.month,"year",b.year,"category",b.category==null?"Overall":b.category.name,"used",used,"remaining",b.amount.subtract(used),"percentage",pct,"status",FinancialRules.budgetStatus(used,b.amount)));});
  List<Map<String,Object>> recentExpenses=allExpenses.stream().limit(10).map(e->Map.<String,Object>of("id",e.id,"date",e.date,"category",e.category.name,"description",e.description,"paymentMethod",e.paymentMethod,"amount",e.amount)).toList();
  List<Map<String,Object>> recentIncome=allIncome.stream().limit(10).map(e->Map.<String,Object>of("id",e.id,"date",e.date,"source",e.source,"description",e.description==null?"":e.description,"amount",e.amount)).toList();
  List<Map<String,String>> insights=new ArrayList<>(); categories.forEach((name,amount)->{if(FinancialRules.highCategorySpending(amount,currentExpense)) insights.add(Map.of("title","High category spending","message","High spending detected in "+name+".","severity","WARNING"));}); if(FinancialRules.spendingIncreased(currentExpense,previousExpense)) insights.add(Map.of("title","Spending increased","message","Spending increased compared with previous month.","severity","WARNING")); if(FinancialRules.lowSavings(currentIncome,currentExpense)) insights.add(Map.of("title","Low savings","message","Consider reducing non-essential expenses.","severity","INFO")); budgetRows.stream().filter(b->"EXCEEDED".equals(b.get("status"))).forEach(b->insights.add(Map.of("title","Budget exceeded","message","The "+b.get("category")+" budget has been exceeded.","severity","DANGER")));
  Map<String,Object> result=new LinkedHashMap<>(); result.put("user",Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"active",u.active,"createdAt",u.createdAt)); result.put("totalIncome",totalIncome); result.put("totalExpense",totalExpense); result.put("balance",balance); result.put("savings",balance); result.put("savingsPercentage",FinancialRules.savingsPercentage(totalIncome,totalExpense)); result.put("currentMonthIncome",currentIncome); result.put("currentMonthExpense",currentExpense); result.put("previousMonthExpense",previousExpense); result.put("spendingIncreased",FinancialRules.spendingIncreased(currentExpense,previousExpense)); result.put("categorySummary",categories); result.put("budgets",budgetRows); result.put("recentExpenses",recentExpenses); result.put("recentIncome",recentIncome); result.put("insights",insights); return result;
 }
}
@RestController @RequestMapping("/api/reports") class ReportController extends Base{final UserRepo us;final IncomeRepo is;final ExpenseRepo es;final BudgetRepo bs;ReportController(UserRepo u,IncomeRepo i,ExpenseRepo e,BudgetRepo b){us=u;is=i;es=e;bs=b;}@GetMapping("/monthly")void monthly(@RequestParam int month,@RequestParam int year,Authentication a,HttpServletResponse response)throws Exception{User u=me(a,us);LocalDate from=LocalDate.of(year,month,1),to=from.plusMonths(1).minusDays(1);var incomes=is.findByUserIdAndDateBetween(u.id,from,to);var expenses=es.findByUserIdAndDateBetween(u.id,from,to);BigDecimal income=incomes.stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add),total=expenses.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add),balance=income.subtract(total);String pct=income.signum()==0?"0.00":balance.multiply(BigDecimal.valueOf(100)).divide(income,2,RoundingMode.HALF_UP).toString();response.setContentType("application/pdf");response.setHeader("Content-Disposition","attachment; filename=SmartSpend-Monthly-Report-"+year+"-"+String.format("%02d",month)+".pdf");Document d=new Document();PdfWriter.getInstance(d,response.getOutputStream());d.open();d.add(new Paragraph("SmartSpend Monthly Financial Report",FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));d.add(new Paragraph("User: "+u.name+" ("+u.email+")"));d.add(new Paragraph("Month/year: "+year+"-"+String.format("%02d",month)));d.add(new Paragraph("Total income: "+income));d.add(new Paragraph("Total expense: "+total));d.add(new Paragraph("Balance / savings: "+balance));d.add(new Paragraph("Savings percentage: "+pct+"%"));Map<String,BigDecimal> summary=new LinkedHashMap<>();expenses.forEach(e->summary.merge(e.category.name,e.amount,BigDecimal::add));d.add(new Paragraph("Category Summary"));d.add(new Paragraph("(category | amount | percentage):"));summary.forEach((name,amount)->{try{String share=total.signum()==0?"0.00":amount.multiply(BigDecimal.valueOf(100)).divide(total,2,RoundingMode.HALF_UP).toString();d.add(new Paragraph(name+" | "+amount+" | "+share+"%"));}catch(Exception ignored){}});d.add(new Paragraph("Budget Summary"));d.add(new Paragraph("(budget | category | amount | used | remaining | usage | status):"));bs.findByUserId(u.id).stream().filter(b->b.month==month&&b.year==year).forEach(b->{try{BigDecimal used=expenses.stream().filter(e->b.category==null||e.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal usage=b.amount.signum()==0?BigDecimal.ZERO:used.multiply(BigDecimal.valueOf(100)).divide(b.amount,2,RoundingMode.HALF_UP);String status=usage.compareTo(BigDecimal.valueOf(100))>=0?"EXCEEDED":usage.compareTo(BigDecimal.valueOf(80))>=0?"WARNING":"SAFE";d.add(new Paragraph("Budget | "+(b.category==null?"Overall":b.category.name)+" | "+b.amount+" | "+used+" | "+b.amount.subtract(used)+" | "+usage+"% | "+status));}catch(Exception ignored){}});d.add(new Paragraph("Insights:"));summary.forEach((name,amount)->{if(total.signum()>0&&amount.multiply(BigDecimal.valueOf(100)).divide(total,2,RoundingMode.HALF_UP).compareTo(BigDecimal.valueOf(30))>0)try{d.add(new Paragraph("High spending detected in "+name+"."));}catch(Exception ignored){}});bs.findByUserId(u.id).stream().filter(b->b.month==month&&b.year==year).forEach(b->{try{BigDecimal used=expenses.stream().filter(e->b.category==null||e.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal usage=b.amount.signum()==0?BigDecimal.ZERO:used.multiply(BigDecimal.valueOf(100)).divide(b.amount,2,RoundingMode.HALF_UP);if(usage.compareTo(BigDecimal.valueOf(100))>=0)d.add(new Paragraph("Budget exceeded."));else if(usage.compareTo(BigDecimal.valueOf(80))>=0)d.add(new Paragraph("Budget approaching limit."));}catch(Exception ignored){}});LocalDate currentStart=from,previousStart=from.minusMonths(1);BigDecimal current=total,previous=es.findByUserIdAndDateBetween(u.id,previousStart,from.minusDays(1)).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);if(current.compareTo(previous)>0)d.add(new Paragraph("Spending increased compared with previous month."));if(income.signum()>0&&balance.multiply(BigDecimal.valueOf(100)).divide(income,2,RoundingMode.HALF_UP).compareTo(BigDecimal.TEN)<0)d.add(new Paragraph("Consider reducing non-essential expenses."));d.add(new Paragraph("Transactions"));d.add(new Paragraph("(date | category | description | payment method | amount):"));for(Expense e:expenses)d.add(new Paragraph(e.date+" | "+e.category.name+" | "+e.description+" | "+e.paymentMethod+" | "+e.amount));d.close();}}
